		'Wenn alles aus dem Ofen kommt' => array( 'Quand tout sort du four', 'When everything comes out of the oven' ),
		'Unten werden die Marktstände aufgebaut, oben duftet es nach frischen Buttergipfeli.' => array( 'En bas, on monte les étals du marché ; en haut, ça sent les croissants au beurre tout frais.', 'Down below the market stalls are being set up; upstairs it smells of fresh butter croissants.' ),
		'Das Rathaus-Frühstück, dazu ein Cüpli' => array( 'Le petit-déjeuner Rathaus, avec une coupe de bulles', 'The Rathaus breakfast, with a glass of bubbly' ),
		'Der Tea Room am frühen Morgen' => array( 'Le salon de thé tôt le matin', 'The Tea Room early in the morning' ),
		'Der Vormittag' => array( 'La matinée', 'Mid-morning' ),
		'Die ruhige Stunde' => array( 'L’heure tranquille', 'The quiet hour' ),
		'Unser Lieblingsmoment' => array( 'Notre moment préféré', 'Our favourite moment' ),
		'Zwischen Frühstück und Mittag werden Tische frei, und das Licht fällt durch die Fenster. Die beste Zeit zum Verweilen.' => array( 'Entre le petit-déjeuner et midi, des tables se libèrent et la lumière entre par les fenêtres. Le meilleur moment pour s’attarder.', 'Between breakfast and lunch, tables free up and light falls through the windows. The best time to linger.' ),
		'Ein Kännchen Darjeeling mit Pralinen' => array( 'Une théière de Darjeeling avec des pralinés', 'A pot of Darjeeling with pralines' ),
		'Der Tea Room am Vormittag' => array( 'Le salon de thé en matinée', 'The Tea Room mid-morning' ),
		'Der Nachmittag' => array( 'L’après-midi', 'The afternoon' ),
		'Kaffee und Kuchen' => array( 'Café et gâteaux', 'Coffee and cake' ),
		'Der Tea Room ist voll' => array( 'Le salon de thé est plein', 'The Tea Room is full' ),
		'Die Stunde, in der der Tea Room am meisten ist, was er immer war: lebendig, fröhlich, mit Tabletts zwischen den Tischen.' => array( 'L’heure où le salon de thé est plus que jamais ce qu’il a toujours été : vivant, joyeux, avec des plateaux entre les tables.', 'The hour when the Tea Room is most what it always was: lively, cheerful, with trays between the tables.' ),
		'Die Trio-Degustation der hausgemachten Schokoladen' => array( 'La dégustation trio des chocolats chauds maison', 'The trio tasting of homemade hot chocolates' ),
		'Kaffee und Kuchen im Tea Room' => array( 'Café et gâteaux au salon de thé', 'Coffee and cake in the Tea Room' ),
		'Der späte Nachmittag' => array( 'La fin d’après-midi', 'Late afternoon' ),
		'Die letzte Tasse' => array( 'La dernière tasse', 'The last cup' ),
		'Bevor sich der Platz leert' => array( 'Avant que la place ne se vide', 'Before the square empties' ),
		'Das Licht wird weicher über dem Marktplatz. Zeit für eine Coupe oder einen Schiesser Eiscafé.' => array( 'La lumière s’adoucit sur le Marktplatz. C’est l’heure d’une coupe glacée ou d’un café glacé Schiesser.', 'The light softens over the Marktplatz. Time for a coupe or a Schiesser iced coffee.' ),
		'Der Schiesser Eiscafé nach altem Rezept' => array( 'Le café glacé Schiesser, selon une recette ancienne', 'The Schiesser iced coffee, made to an old recipe' ),
		'Der Tea Room am späten Nachmittag' => array( 'Le salon de thé en fin d’après-midi', 'The Tea Room in the late afternoon' ),
		'Der Tea Room ist frei zugänglich, ohne Reservation.' => array( 'Le salon de thé est en accès libre, sans réservation.', 'The Tea Room is open to everyone, no reservation needed.' ),
		'Ein Tisch wartet auf Sie' => array( 'Une table vous attend', 'A table is waiting for you' ),
		'Treten Sie in den Laden, gehen Sie bis zur Treppe und steigen Sie hinauf. Meist ist ein Platz am Fenster frei.' => array( 'Entrez dans la boutique, allez jusqu’à l’escalier et montez. Une place près de la fenêtre est souvent libre.', 'Step into the shop, walk to the staircase and go up. There is usually a seat free by the window.' ),
		'Ein Tisch am Fenster im Tea Room' => array( 'Une table près de la fenêtre au salon de thé', 'A table by the window in the Tea Room' ),
		'Erster Stock, Zugang durch den Laden' => array( 'Premier étage, accès par la boutique', 'First floor, access through the shop' ),
		'Nicht nötig' => array( 'Pas nécessaire', 'Not necessary' ),
		'Empfohlen ab sechs Personen oder für einen privaten Anlass' => array( 'Conseillée dès six personnes ou pour un événement privé', 'Recommended from six people or for a private event' ),
		'Auf Anfrage' => array( 'Sur demande', 'On request' ),
		'Degustationen und private Anlässe' => array( 'Dégustations et événements privés', 'Tastings and private events' ),
		'Fragen zu unserem Tea Room in Basel' => array( 'Questions sur notre salon de thé à Bâle', 'Questions about our Tea Room in Basel' ),
		'Reservation, Gruppen und Karte.' => array( 'Réservation, groupes et carte.', 'Reservations, groups and menu.' ),
		'Muss man im Tea Room reservieren?' => array( 'Faut-il réserver au salon de thé ?', 'Do I need to book a table in the Tea Room?' ),
		'Nein, der Zugang ist frei. Ab sechs Personen empfehlen wir eine Reservation: <a href="{H}/kontakt/">rufen Sie uns an oder schreiben Sie uns</a>. <a href="{H}/besuch/">Öffnungszeiten und Anfahrt zum Marktplatz</a>.' => array( 'Non, l’accès est libre. Dès six personnes, nous conseillons de réserver : <a href="{H}/kontakt/">appelez-nous ou écrivez-nous</a>. <a href="{H}/besuch/">Horaires et accès au Marktplatz</a>.', 'No, it is open to everyone. For six people or more we recommend a reservation: <a href="{H}/kontakt/">call us or write to us</a>. <a href="{H}/besuch/">Opening hours and directions to the Marktplatz</a>.' ),
		'Kann man den Tea Room privat mieten?' => array( 'Peut-on privatiser le salon de thé ?', 'Can the Tea Room be booked privately?' ),
		'Je nach Zeit und Saison ist das möglich. <a href="{H}/kontakt/">Kontaktieren Sie uns</a> mit Datum, Anzahl Personen und Ihren Wünschen.' => array( 'Selon l’heure et la saison, c’est possible. <a href="{H}/kontakt/">Contactez-nous</a> en indiquant la date, le nombre de personnes et vos souhaits.', 'Depending on the time and season, it is possible. <a href="{H}/kontakt/">Contact us</a> with the date, the number of people and your wishes.' ),
		'Gibt es auch etwas Herzhaftes?' => array( 'Y a-t-il aussi du salé ?', 'Is there anything savoury?' ),
		'Ja: Tagessuppe und Tomatencreme mit Hausbrot, hausgemachte Quiches, Salatteller und Hauspasteten-Teller, dazu Schinkengipfel und Wurstwegge aus unserer <a href="{H}/confiserie/">Backstube am Marktplatz</a>.' => array( 'Oui : soupe du jour et crème de tomates avec pain maison, quiches maison, assiettes de salade et assiette de pâtés maison, ainsi que croissants au jambon et feuilletés à la saucisse de notre <a href="{H}/confiserie/">atelier du Marktplatz</a>.', 'Yes: soup of the day and cream of tomato soup with house bread, homemade quiches, salad plates and a house pie platter, plus ham croissants and sausage rolls from our <a href="{H}/confiserie/">bakehouse on the Marktplatz</a>.' ),
		'Kann man bei Ihnen frühstücken?' => array( 'Peut-on prendre le petit-déjeuner chez vous ?', 'Can I have breakfast with you?' ),
		'Ja: Marktplatz-, Schiesser- und Rathaus-Frühstück mit hausgemachten Buttergipfeln und frisch gepresstem Orangensaft, auf Wunsch mit einem Cüpli Prosecco oder Champagner. Seit wann hier gefrühstückt wird, erzählt unsere <a href="{H}/geschichte/">Geschichte seit 1870</a>.' => array( 'Oui : petit-déjeuner Marktplatz, Schiesser ou Rathaus, avec croissants au beurre maison et jus d’orange pressé, sur demande avec une coupe de prosecco ou de champagne. Depuis quand on prend son petit-déjeuner ici ? Notre <a href="{H}/geschichte/">histoire depuis 1870</a> vous le raconte.', 'Yes: the Marktplatz, Schiesser or Rathaus breakfast, with homemade butter croissants and freshly squeezed orange juice, and a glass of prosecco or champagne if you like. How long breakfast has been served here is told in our <a href="{H}/geschichte/">history since 1870</a>.' ),
		'Seit 1870 · Marktplatz' => array( 'Depuis 1870 · Marktplatz', 'Since 1870 · Marktplatz' ),
		'Seit 1870 <br><em>am Basler Marktplatz</em>' => array( 'Depuis 1870 <br><em>sur le Marktplatz de Bâle</em>', 'Since 1870 <br><em>on the Marktplatz in Basel</em>' ),
		'Die Geschichte einer Basler Confiserie, die ein Glarner Konditor gründete und die bis heute Kaffeehaus, Tea Room und Backstube unter einem Dach vereint.' => array( 'L’histoire d’une confiserie bâloise fondée par un confiseur glaronais, qui réunit aujourd’hui encore café, salon de thé et atelier sous un même toit.', 'The story of a Basel confectionery founded by a confectioner from Glarus, which still brings together a coffee house, a Tea Room and a bakehouse under one roof.' ),
		'Gründungsjahr' => array( 'Année de fondation', 'Year founded' ),
		'Jahre Handwerk' => array( 'ans de savoir-faire', 'years of craftsmanship' ),
		'Adresse am Marktplatz' => array( 'adresse sur le Marktplatz', 'address on the Marktplatz' ),
		'Etagen: Confiserie und Tea Room' => array( 'étages : confiserie et salon de thé', 'floors: confectionery and Tea Room' ),
		'Jahre Schiesser' => array( 'ans Schiesser', 'years of Schiesser' ),
		'Anderthalb Jahrhunderte Handwerk, von Generation zu Generation weitergegeben.' => array( 'Un siècle et demi de savoir-faire, transmis de génération en génération.', 'A century and a half of craftsmanship, handed down from generation to generation.' ),
		'Der Anfang' => array( 'Les débuts', 'The beginning' ),
		'Eine Geschichte, einfach erzählt. Der Rest lässt sich vor Ort geniessen.' => array( 'Une histoire, racontée simplement. Le reste se savoure sur place.', 'A story, simply told. The rest is best enjoyed on the spot.' ),
		'Archiv · die Fassade um 1889' => array( 'Archives · la façade vers 1889', 'Archive · the façade around 1889' ),
		'Abb. 01' => array( 'Fig. 01', 'Fig. 01' ),
		'<p>Der Glarner Konditor Rudolf Schiesser legte 1870 den Grundstein: eine <a href="{H}/confiserie/">Confiserie am Basler Marktplatz</a>, direkt <a href="{H}/besuch/">gegenüber dem Rathaus</a>.</p>' => array( '<p>En 1870, le confiseur glaronais Rudolf Schiesser pose la première pierre : une <a href="{H}/confiserie/">confiserie sur le Marktplatz de Bâle</a>, juste <a href="{H}/besuch/">en face de l’Hôtel de Ville</a>.</p>', '<p>In 1870 the Glarus confectioner Rudolf Schiesser laid the foundation stone: a <a href="{H}/confiserie/">confectionery on the Marktplatz in Basel</a>, right <a href="{H}/besuch/">opposite the Town Hall</a>.</p>' ),
		'<p>Schon früh stand auf der Fassade, wofür das Haus bekannt wurde: «Patisserie», «Leckerly», «Schiesser Confiseur». Gebacken wurde im Haus, verkauft an der Theke, der Markt lag direkt vor der Tür. Die <a href="{H}/confiserie/">Basler Läckerli</a> gehören bis heute dazu.</p>' => array( '<p>Très tôt, la façade annonçait ce qui fera la réputation de la maison : «&nbsp;Patisserie&nbsp;», «&nbsp;Leckerly&nbsp;», «&nbsp;Schiesser Confiseur&nbsp;». On cuisait dans la maison, on vendait au comptoir, le marché se tenait juste devant la porte. Les <a href="{H}/confiserie/">Läckerli de Bâle</a> en font toujours partie.</p>', '<p>Early on, the façade already announced what the house would become known for: “Patisserie”, “Leckerly”, “Schiesser Confiseur”. Baking was done in the house, selling at the counter, and the market was right outside the door. <a href="{H}/confiserie/">Basel Läckerli</a> are still part of it today.</p>' ),
		'Was wir Ihnen servieren, entsteht wie damals im Haus, zum Teil nach Rezepten aus den Gründerjahren.' => array( 'Ce que nous vous servons est fait dans la maison comme autrefois, parfois selon des recettes des premières années.', 'What we serve you is made in the house as it always was, some of it from recipes dating back to the early years.' ),
		'Confiserie Schiesser' => array( 'Confiserie Schiesser', 'Confiserie Schiesser' ),
		'<p>Sein Sohn Hans gab dem Haus die neugotische Fassade nach dem Vorbild des Rathauses und richtete im ersten Stock den <a href="{H}/tea-room/">Tea Room</a> und das «Rathstübli» ein. Seither debattieren und geniessen dort Baslerinnen und Basler wie Gäste aus aller Welt.</p>' => array( '<p>Son fils Hans a donné à la maison sa façade néogothique, inspirée de l’Hôtel de Ville, et aménagé au premier étage le <a href="{H}/tea-room/">salon de thé</a> et le «&nbsp;Rathstübli&nbsp;». Depuis, Bâloises et Bâlois comme visiteurs du monde entier y discutent et s’y régalent.</p>', '<p>His son Hans gave the house its neo-Gothic façade, modelled on the Town Hall, and fitted out the <a href="{H}/tea-room/">Tea Room</a> and the “Rathstübli” on the first floor. Ever since, people from Basel and guests from all over the world have been talking and enjoying themselves there.</p>' ),
		'Die Chronik' => array( 'La chronique', 'The chronicle' ),
		'Wählen Sie ein Datum oder lassen Sie die Geschichte laufen.' => array( 'Choisissez une date ou laissez défiler l’histoire.', 'Choose a date or let the story play.' ),
		'Klicken Sie auf ein Datum' => array( 'Cliquez sur une date', 'Click on a date' ),
		'Gründung' => array( 'Fondation', 'Founding' ),
		'Rudolf Schiesser, Konditor aus Glarus, eröffnet seine Confiserie am Basler Marktplatz.' => array( 'Rudolf Schiesser, confiseur venu de Glaris, ouvre sa confiserie sur le Marktplatz de Bâle.', 'Rudolf Schiesser, a confectioner from Glarus, opens his confectionery on the Marktplatz in Basel.' ),
		'Das Haus steht bis heute an derselben Adresse, gegenüber dem Rathaus.' => array( 'La maison se trouve toujours à la même adresse, en face de l’Hôtel de Ville.', 'The house is still at the same address, opposite the Town Hall.' ),
		'Patisserie und Leckerly' => array( 'Patisserie et Leckerly', 'Patisserie and Leckerly' ),
		'Die Aufnahme von 1889 zeigt die Fassade mit «Patisserie», «Leckerly» und «Schiesser Confiseur», in den Fenstern das Personal des Hauses.' => array( 'La photographie de 1889 montre la façade avec «&nbsp;Patisserie&nbsp;», «&nbsp;Leckerly&nbsp;» et «&nbsp;Schiesser Confiseur&nbsp;», et aux fenêtres le personnel de la maison.', 'The 1889 photograph shows the façade with “Patisserie”, “Leckerly” and “Schiesser Confiseur”, and the staff of the house at the windows.' ),
		'Läckerli gehören seit den Anfängen zum Haus.' => array( 'Les Läckerli font partie de la maison depuis ses débuts.', 'Läckerli have been part of the house since the very beginning.' ),
