		'≈ 8 Min.' => array( '≈ 8 min', '≈ 8 min' ),
		'Haltestelle Marktplatz' => array( 'Arrêt Marktplatz', 'Marktplatz stop' ),
		'Aussteigen auf dem Platz. Unsere Vitrine liegt gegenüber dem Rathaus.' => array( 'Descendez sur la place. Notre vitrine se trouve face à l’Hôtel de Ville.', 'Get off on the square. Our window is opposite the Town Hall.' ),
		'≈ 1 Min.' => array( '≈ 1 min', '≈ 1 min' ),
		'Sie sind da. Treten Sie ein, die Vitrine ist frisch bestückt.' => array( 'Vous y êtes. Entrez, la vitrine vient d’être garnie.', 'You are here. Come in, the window has just been restocked.' ),
		'Flughafen Basel-Mulhouse' => array( 'Aéroport de Bâle-Mulhouse', 'Basel-Mulhouse Airport' ),
		'Vom EuroAirport' => array( 'Depuis l’EuroAirport', 'From the EuroAirport' ),
		'Mit Bus und Tram ins Zentrum.' => array( 'En bus et en tram jusqu’au centre.', 'By bus and tram to the centre.' ),
		'Nehmen Sie den Schweizer Ausgang des Flughafens; der französische führt auf die andere Seite der Grenze.' => array( 'Prenez la sortie suisse de l’aéroport ; la sortie française mène de l’autre côté de la frontière.', 'Take the Swiss exit of the airport; the French exit leads to the other side of the border.' ),
		'Verlassen Sie das Terminal auf der Schweizer Seite und gehen Sie zu den Bushaltestellen.' => array( 'Quittez le terminal côté suisse et rendez-vous aux arrêts de bus.', 'Leave the terminal on the Swiss side and go to the bus stops.' ),
		'Bus ins Zentrum' => array( 'Bus vers le centre', 'Bus to the centre' ),
		'Nehmen Sie den Bus zum Bahnhof Basel SBB.' => array( 'Prenez le bus jusqu’à la gare de Bâle CFF.', 'Take the bus to Basel SBB station.' ),
		'≈ 20 Min.' => array( '≈ 20 min', '≈ 20 min' ),
		'Basel SBB, dann Marktplatz' => array( 'Bâle CFF, puis Marktplatz', 'Basel SBB, then Marktplatz' ),
		'Steigen Sie in ein Tram zum Marktplatz um.' => array( 'Changez pour un tram en direction du Marktplatz.', 'Change to a tram to Marktplatz.' ),
		'≈ 10 Min.' => array( '≈ 10 min', '≈ 10 min' ),
		'Der Laden liegt direkt am Platz.' => array( 'La boutique donne directement sur la place.', 'The shop is right on the square.' ),
		'Sie sind schon im Zentrum' => array( 'Vous êtes déjà au centre', 'You are already in the centre' ),
		'Aus der Altstadt' => array( 'Depuis la vieille ville', 'From the Old Town' ),
		'Wenige Gehminuten, alles Fussgängerzone.' => array( 'Quelques minutes à pied, tout en zone piétonne.', 'A few minutes on foot, all pedestrian zone.' ),
		'Am Morgen werden vor dem Laden die Marktstände aufgebaut: die schönste Zeit zum Bummeln. Ideen für Spaziergänge auf <a href="https://www.basel.com/de">basel.com</a>.' => array( 'Le matin, les étals du marché s’installent devant la boutique : le meilleur moment pour flâner. Des idées de promenades sur <a href="https://www.basel.com/fr">basel.com</a>.', 'In the morning the market stalls are set up in front of the shop: the best time for a stroll. Ideas for walks at <a href="https://www.basel.com/en">basel.com</a>.' ),
		'Aus den Gassen der Altstadt gehen Sie zur Freien Strasse.' => array( 'Depuis les ruelles de la vieille ville, rejoignez la Freie Strasse.', 'From the lanes of the Old Town, make your way to Freie Strasse.' ),
		'Freie Strasse' => array( 'Freie Strasse', 'Freie Strasse' ),
		'Folgen Sie der Einkaufsstrasse Richtung Marktplatz.' => array( 'Suivez la rue commerçante en direction du Marktplatz.', 'Follow the shopping street towards the Marktplatz.' ),
		'≈ 6 Min.' => array( '≈ 6 min', '≈ 6 min' ),
		'Die Strasse mündet auf den Platz. Wir sind gegenüber dem Rathaus.' => array( 'La rue débouche sur la place. Nous sommes face à l’Hôtel de Ville.', 'The street opens onto the square. We are opposite the Town Hall.' ),
		'≈ 2 Min.' => array( '≈ 2 min', '≈ 2 min' ),
		'Mit dem Auto' => array( 'En voiture', 'By car' ),
		'Von der Autobahn' => array( 'Depuis l’autoroute', 'From the motorway' ),
		'Der Marktplatz ist Fussgängerzone, parkiert wird in der Nähe.' => array( 'Le Marktplatz est une zone piétonne, on se gare à proximité.', 'The Marktplatz is a pedestrian zone; park nearby.' ),
		'Rund um den Platz ist der Verkehr eingeschränkt. Wenn möglich ist das Tram einfacher und schneller.' => array( 'La circulation est limitée autour de la place. Si possible, le tram est plus simple et plus rapide.', 'Traffic around the square is restricted. If possible, the tram is easier and faster.' ),
		'Folgen Sie der Richtung Basel Zentrum.' => array( 'Suivez la direction Basel Zentrum.', 'Follow the signs for Basel Zentrum.' ),
		'Parkhaus im Zentrum' => array( 'Parking au centre', 'Car park in the centre' ),
		'Parkieren Sie in einem der Parkhäuser nahe der Innenstadt.' => array( 'Garez-vous dans l’un des parkings proches du centre-ville.', 'Park in one of the car parks near the city centre.' ),
		'≈ 15 Min.' => array( '≈ 15 min', '≈ 15 min' ),
		'Zu Fuss zum Platz' => array( 'À pied jusqu’à la place', 'On foot to the square' ),
		'Durch die Fussgängerzone zum Marktplatz.' => array( 'Par la zone piétonne jusqu’au Marktplatz.', 'Through the pedestrian zone to the Marktplatz.' ),
		'Sie stehen direkt vor dem Laden.' => array( 'Vous êtes juste devant la boutique.', 'You are standing right in front of the shop.' ),
		'Praktisches vor Ihrem Besuch.' => array( 'Infos pratiques avant votre visite.', 'Practical information before your visit.' ),
		'Wir empfangen Sie auf Deutsch, Französisch und Englisch.' => array( 'Nous vous accueillons en allemand, en français et en anglais.', 'We welcome you in German, French and English.' ),
		'Der Laden ist vom Platz aus ebenerdig. Der Tea Room liegt im ersten Stock und ist über eine Treppe erreichbar. Sagen Sie uns Bescheid, wir helfen gerne.' => array( 'La boutique est de plain-pied depuis la place. Le salon de thé se trouve au premier étage et se rejoint par un escalier. Prévenez-nous, nous vous aidons volontiers.', 'The shop is at street level from the square. The Tea Room is on the first floor and is reached by a staircase. Let us know and we will be glad to help.' ),
		'Zum Mitnehmen' => array( 'À emporter', 'To take away' ),
		'Alle Produkte gibt es zum Mitnehmen, auf Wunsch reisefest verpackt.' => array( 'Tous les produits sont disponibles à emporter, emballés pour le voyage sur demande.', 'All products are available to take away, packed for travelling on request.' ),
		'Pralinen, Läckerli und Bonbonnière, von Hand zusammengestellt und schön verpackt.' => array( 'Pralinés, Läckerli et bonbonnière, composés à la main et joliment emballés.', 'Pralines, Läckerli and bonbonnière, put together by hand and beautifully packed.' ),
		'Fussgängerzone' => array( 'Zone piétonne', 'Pedestrian zone' ),
		'Der Marktplatz ist Fussgängerzone: zu Fuss aus den Nachbarstrassen oder mit dem Tram.' => array( 'Le Marktplatz est une zone piétonne : à pied depuis les rues voisines ou en tram.', 'The Marktplatz is a pedestrian zone: on foot from the neighbouring streets or by tram.' ),
		'Das Haus erkennen' => array( 'Reconnaître la maison', 'Recognising the house' ),
		'Danach halten Sie Ausschau, wenn Sie auf den Platz kommen.' => array( 'Voici ce qu’il faut chercher en arrivant sur la place.', 'Here is what to look out for when you reach the square.' ),
		'Marktplatz · gegenüber dem Rathaus' => array( 'Marktplatz · face à l’Hôtel de Ville', 'Marktplatz · opposite the Town Hall' ),
		'Die neugotische Fassade nach dem Vorbild des Rathauses, die Vitrinen direkt am Platz. Der Eingang führt durch den Laden, die Treppe zum Tea Room liegt hinten.' => array( 'La façade néogothique inspirée de l’Hôtel de Ville, les vitrines directement sur la place. L’entrée se fait par la boutique, l’escalier vers le salon de thé est au fond.', 'The neo-Gothic façade modelled on the Town Hall, the windows right on the square. The entrance leads through the shop; the staircase to the Tea Room is at the back.' ),
		'Die Fassade der Confiserie Schiesser am Marktplatz Basel' => array( 'La façade de la Confiserie Schiesser sur le Marktplatz de Bâle', 'The façade of Confiserie Schiesser on the Marktplatz in Basel' ),
		'Praktische Fragen vor Ihrem Besuch' => array( 'Questions pratiques avant votre visite', 'Practical questions before your visit' ),
		'Gibt es Parkplätze in der Nähe?' => array( 'Y a-t-il des places de parc à proximité ?', 'Is there parking nearby?' ),
		'Der Marktplatz ist Fussgängerzone. Die Parkhäuser der Innenstadt liegen wenige Gehminuten entfernt. Fragen vor Ihrem Besuch? <a href="{H}/kontakt/">Kontaktieren Sie uns</a>.' => array( 'Le Marktplatz est une zone piétonne. Les parkings du centre-ville sont à quelques minutes à pied. Une question avant votre visite ? <a href="{H}/kontakt/">Contactez-nous</a>.', 'The Marktplatz is a pedestrian zone. The city-centre car parks are a few minutes’ walk away. Any questions before your visit? <a href="{H}/kontakt/">Contact us</a>.' ),
		'Kann man mit Euro bezahlen?' => array( 'Peut-on payer en euros ?', 'Can I pay in euros?' ),
		'Ja, Euro werden im Laden angenommen. Ausserdem Karten, kontaktlos und bar in Schweizer Franken.' => array( 'Oui, les euros sont acceptés en boutique. Ainsi que les cartes, le sans contact et les espèces en francs suisses.', 'Yes, euros are accepted in the shop. So are cards, contactless payments and cash in Swiss francs.' ),
		'Wo kann man vor Ort etwas geniessen?' => array( 'Où peut-on se régaler sur place ?', 'Where can I enjoy something on site?' ),
		'Im <a href="{H}/tea-room/">Tea Room</a> im ersten Stock, während der Öffnungszeiten der Confiserie: Kaffee, Tee, hausgemachte Schokolade, Frühstück und Desserts.' => array( 'Au <a href="{H}/tea-room/">salon de thé</a> du premier étage, pendant les heures d’ouverture de la confiserie : café, thé, chocolat chaud maison, petit-déjeuner et desserts.', 'In the <a href="{H}/tea-room/">Tea Room</a> on the first floor, during the confectionery’s opening hours: coffee, tea, homemade hot chocolate, breakfast and desserts.' ),
		'Unsere Geschenkboxen sind zum Mitnehmen gemacht. Fragen Sie nach einer bruchsicheren Verpackung, wenn Sie fliegen oder mit dem Zug reisen. Alle Spezialitäten finden Sie in unserer <a href="{H}/confiserie/">Confiserie in Basel</a>.' => array( 'Nos coffrets cadeaux sont faits pour être emportés. Demandez un emballage incassable si vous prenez l’avion ou le train. Toutes nos spécialités vous attendent dans notre <a href="{H}/confiserie/">confiserie à Bâle</a>.', 'Our gift boxes are made to be taken away. Ask for unbreakable packaging if you are flying or travelling by train. You will find all our specialities in our <a href="{H}/confiserie/">confectionery in Basel</a>.' ),
		'Was gibt es rund um den Marktplatz zu sehen?' => array( 'Que voir autour du Marktplatz ?', 'What is there to see around the Marktplatz?' ),
		'Das Rathaus liegt direkt gegenüber, die Altstadt beginnt gleich nebenan. Ideen für Spaziergänge auf <a href="https://www.basel.com/de">basel.com</a>.' => array( 'L’Hôtel de Ville se trouve juste en face, la vieille ville commence tout à côté. Des idées de promenades sur <a href="https://www.basel.com/fr">basel.com</a>.', 'The Town Hall is right opposite and the Old Town begins next door. Ideas for walks at <a href="https://www.basel.com/en">basel.com</a>.' ),
		'Eine Frage, eine Bestellung, ein Anlass' => array( 'Une question, une commande, un événement', 'A question, an order, an occasion' ),
		'Kontakt zur <br><em>Confiserie Schiesser</em>' => array( 'Contacter la <br><em>Confiserie Schiesser</em>', 'Contact <br><em>Confiserie Schiesser</em>' ),
		'Eine Nachricht, ein Anruf oder ein Besuch am Marktplatz: wir beantworten jede Anfrage.' => array( 'Un message, un appel ou une visite sur le Marktplatz : nous répondons à chaque demande.', 'A message, a call or a visit to the Marktplatz: we answer every enquiry.' ),
		'Die Theke der Confiserie Schiesser' => array( 'Le comptoir de la Confiserie Schiesser', 'The counter of Confiserie Schiesser' ),
		'Während der Öffnungszeiten' => array( 'Pendant les heures d’ouverture', 'During opening hours' ),
		'Antwort innert 1 bis 2 Arbeitstagen' => array( 'Réponse sous 1 à 2 jours ouvrables', 'Reply within 1 to 2 working days' ),
		'Eine kurze Nachricht genügt, wir antworten innert ein bis zwei Arbeitstagen.' => array( 'Un court message suffit, nous répondons sous un à deux jours ouvrables.', 'A short message is enough; we reply within one or two working days.' ),
		'Ihre Nachricht' => array( 'Votre message', 'Your message' ),
		'Ihre Angaben verwenden wir nur, um Ihre Anfrage zu bearbeiten.' => array( 'Nous utilisons vos données uniquement pour traiter votre demande.', 'We only use your details to handle your enquiry.' ),
		'Ihre Nachricht ist unterwegs' => array( 'Votre message est en route', 'Your message is on its way' ),
		'Vielen Dank. Wir antworten innert ein bis zwei Arbeitstagen.' => array( 'Merci beaucoup. Nous vous répondons sous un à deux jours ouvrables.', 'Thank you very much. We will reply within one or two working days.' ),
		'Während der Öffnungszeiten, am schnellsten bei dringenden Fragen.' => array( 'Pendant les heures d’ouverture, le plus rapide pour les questions urgentes.', 'During opening hours, the quickest way for urgent questions.' ),
		'Antwort innert ein bis zwei Arbeitstagen.' => array( 'Réponse sous un à deux jours ouvrables.', 'Reply within one or two working days.' ),
		'Am einfachsten: kommen Sie vorbei.' => array( 'Le plus simple : passez nous voir.', 'The easiest way: drop by.' ),
		'Erreichen Sie uns' => array( 'Nous joindre', 'Get in touch' ),
		'Eine Adresse, ein Team, für Confiserie und Tea Room.' => array( 'Une adresse, une équipe, pour la confiserie et le salon de thé.', 'One address, one team, for the confectionery and the Tea Room.' ),
		'Im Erdgeschoss die Confiserie, im ersten Stock der Tea Room. Für eine Bestellung, eine Frage oder eine Gruppenreservation: schreiben Sie uns oder rufen Sie an, unser Team antwortet Ihnen.' => array( 'Au rez-de-chaussée la confiserie, au premier étage le salon de thé. Pour une commande, une question ou une réservation de groupe : écrivez-nous ou appelez-nous, notre équipe vous répond.', 'The confectionery on the ground floor, the Tea Room on the first floor. For an order, a question or a group reservation: write to us or give us a call, our team will answer.' ),
		'Für' => array( 'Pour', 'For' ),
		'Bestellungen, Torten, Geschenkboxen, Gruppen, Presse' => array( 'Commandes, gâteaux, coffrets cadeaux, groupes, presse', 'Orders, cakes, gift boxes, groups, press' ),
		'Bevor Sie uns schreiben' => array( 'Avant de nous écrire', 'Before you write to us' ),
		'Vielleicht steht die Antwort schon hier.' => array( 'La réponse se trouve peut-être déjà ici.', 'The answer may already be here.' ),
		'Wie schnell antworten Sie?' => array( 'En combien de temps répondez-vous ?', 'How quickly do you reply?' ),
		'Per E-Mail innert ein bis zwei Arbeitstagen. Bei dringenden Anliegen rufen Sie uns am besten während der Öffnungszeiten an.' => array( 'Par e-mail sous un à deux jours ouvrables. Pour les demandes urgentes, le mieux est de nous appeler pendant les heures d’ouverture.', 'By email within one or two working days. For urgent matters it is best to call us during opening hours.' ),
		'Wie früh sollte man eine Torte bestellen?' => array( 'Combien de temps à l’avance commander un gâteau ?', 'How far ahead should I order a cake?' ),
		'Für die meisten Torten genügen wenige Tage, für grosse Bestellungen oder an Festtagen etwas mehr. Rufen Sie uns an, wir beraten Sie gerne. Unser Sortiment an Torten, Läckerli und Pralinen finden Sie in der <a href="{H}/confiserie/">Confiserie</a>.' => array( 'Pour la plupart des gâteaux, quelques jours suffisent ; pour les grosses commandes ou les jours de fête, un peu plus. Appelez-nous, nous vous conseillons volontiers. Notre assortiment de gâteaux, de Läckerli et de pralinés se trouve dans la <a href="{H}/confiserie/">confiserie</a>.', 'For most cakes a few days are enough; for large orders or on holidays, a little more. Give us a call, we will be glad to advise you. You will find our range of cakes, Läckerli and pralines in the <a href="{H}/confiserie/">confectionery</a>.' ),
		'Kann man im Tea Room einen Tisch reservieren?' => array( 'Peut-on réserver une table au salon de thé ?', 'Can I reserve a table in the Tea Room?' ),
		'Der Tea Room ist frei zugänglich. Ab sechs Personen oder für einen privaten Anlass empfehlen wir eine Reservation. Mehr dazu auf der Seite <a href="{H}/tea-room/">Tea Room</a>.' => array( 'Le salon de thé est en accès libre. Dès six personnes ou pour un événement privé, nous conseillons de réserver. Plus d’informations sur la page <a href="{H}/tea-room/">Salon de thé</a>.', 'The Tea Room is open to everyone. For six people or more, or for a private event, we recommend a reservation. More on the <a href="{H}/tea-room/">Tea Room</a> page.' ),
		'Bestellungen holen Sie im Laden am Marktplatz ab. Für besondere Wünsche schreiben Sie uns, wir finden gemeinsam eine Lösung.' => array( 'Les commandes se retirent à la boutique du Marktplatz. Pour des demandes particulières, écrivez-nous, nous trouverons ensemble une solution.', 'Orders are collected from the shop on the Marktplatz. For special requests, write to us and we will find a solution together.' ),
		'Bieten Sie Firmengeschenke an?' => array( 'Proposez-vous des cadeaux d’entreprise ?', 'Do you offer corporate gifts?' ),
		'Ja, wir stellen Pralinen- und Läckerli-Boxen für Ihre Kundschaft oder Ihr Team zusammen, mit Ihrer Botschaft oder Ihrem Logo. Siehe <a href="{H}/firmengeschenke/">Firmengeschenke</a>.' => array( 'Oui, nous composons des boîtes de pralinés et de Läckerli pour vos clients ou votre équipe, avec votre message ou votre logo. Voir <a href="{H}/firmengeschenke/">Cadeaux d’entreprise</a>.', 'Yes, we put together praline and Läckerli boxes for your clients or your team, with your message or logo. See <a href="{H}/firmengeschenke/">Corporate gifts</a>.' ),
		'Gibt es einen Onlineshop?' => array( 'Y a-t-il une boutique en ligne ?', 'Is there an online shop?' ),
		'Er folgt in Kürze. Bis dahin bestellen Sie telefonisch oder per E-Mail und holen alles im Laden am Marktplatz ab: <a href="{H}/besuch/">Öffnungszeiten und Anfahrt</a>.' => array( 'Elle arrive bientôt. D’ici là, commandez par téléphone ou par e-mail et retirez tout à la boutique du Marktplatz : <a href="{H}/besuch/">horaires et accès</a>.', 'It is coming soon. Until then, order by phone or email and collect everything from the shop on the Marktplatz: <a href="{H}/besuch/">opening hours and directions</a>.' ),
		'Am einfachsten ist es immer noch' => array( 'Le plus simple reste encore', 'The easiest way is still' ),
		'Kommen Sie an den Marktplatz' => array( 'Venez sur le Marktplatz', 'Come to the Marktplatz' ),
		'Wir sind vom Morgen bis am Abend für Sie da, die Vitrine ist jeden Tag frisch bestückt und oben wartet der Tea Room.' => array( 'Nous vous accueillons du matin au soir, la vitrine est garnie chaque jour et le salon de thé vous attend à l’étage.', 'We are here for you from morning to evening, the window is restocked every day and the Tea Room is waiting upstairs.' ),
		'Rufen Sie uns an' => array( 'Appelez-nous', 'Call us' ),
		'Für Firmen · Kundschaft und Team' => array( 'Pour les entreprises · clients et équipe', 'For companies · clients and team' ),
		'Firmengeschenke <br><em>aus Basel, von Hand gemacht</em>' => array( 'Cadeaux d’entreprise <br><em>de Bâle, faits main</em>', 'Corporate gifts <br><em>from Basel, handmade</em>' ),
		'Danken Sie Ihrer Kundschaft und Ihrem Team mit Pralinen und Läckerli aus unserer Backstube am Marktplatz, seit 1870.' => array( 'Remerciez vos clients et votre équipe avec des pralinés et des Läckerli de notre atelier du Marktplatz, depuis 1870.', 'Thank your clients and your team with pralines and Läckerli from our bakehouse on the Marktplatz, since 1870.' ),
		'Offerte anfragen' => array( 'Demander une offre', 'Request a quote' ),
		'Pralinenboxen als Firmengeschenke aus Basel' => array( 'Boîtes de pralinés en cadeaux d’entreprise de Bâle', 'Praline boxes as corporate gifts from Basel' ),
		'Innert 1 bis 2 Arbeitstagen' => array( 'Sous 1 à 2 jours ouvrables', 'Within 1 to 2 working days' ),
		'Per E-Mail oder Telefon' => array( 'Par e-mail ou par téléphone', 'By email or phone' ),
		'Unsere Geschenke für Firmen' => array( 'Nos cadeaux pour les entreprises', 'Our gifts for companies' ),
		'Firmengeschenke aus Basel, die gut reisen und lange halten.' => array( 'Des cadeaux d’entreprise de Bâle qui voyagent bien et se conservent longtemps.', 'Corporate gifts from Basel that travel well and keep for a long time.' ),
		'4er-, 9er- oder 16er-Box mit Pralinen aus eigener Produktion, schön verpackt. Auch als Basler Pralinen.' => array( 'Boîte de 4, 9 ou 16 pralinés de notre propre production, joliment emballée. Existe aussi en pralinés bâlois.', 'Box of 4, 9 or 16 pralines from our own production, beautifully packed. Also available as Basel pralines.' ),
		'Basler Läckerli' => array( 'Läckerli de Bâle', 'Basel Läckerli' ),
		'Die Spezialität der Stadt, in der Läckerli-Box oder zu 200 und 500 g: ein Geschenk, das reist und mehrere Wochen hält.' => array( 'La spécialité de la ville, en boîte de Läckerli ou en 200 et 500 g : un cadeau qui voyage et se conserve plusieurs semaines.', 'The city’s speciality, in the Läckerli box or in 200 and 500 g packs: a gift that travels and keeps for several weeks.' ),
		'Bonbonnière' => array( 'Bonbonnière', 'Bonbonnière' ),
		'Das grosse Geschenk: 280, 500 oder 850 g feinste Confiserie.' => array( 'Le grand cadeau : 280, 500 ou 850 g de confiserie fine.', 'The big present: 280, 500 or 850 g of the finest confectionery.' ),
		'Ihre Botschaft, Ihr Logo' => array( 'Votre message, votre logo', 'Your message, your logo' ),
		'Jede Box kann Ihre Botschaft oder Ihr Logo tragen: eine persönliche Aufmerksamkeit, von Hand zusammengestellt.' => array( 'Chaque boîte peut porter votre message ou votre logo : une attention personnelle, composée à la main.', 'Every box can carry your message or logo: a personal touch, put together by hand.' ),
		'<p>Sagen Sie uns, was darauf stehen soll: wir schlagen Ihnen die passende Präsentation für Ihre Menge und Ihr Datum vor.</p>' => array( '<p>Dites-nous ce qui doit y figurer : nous vous proposons la présentation adaptée à votre quantité et à votre date.</p>', '<p>Tell us what it should say: we will suggest the right presentation for your quantity and your date.</p>' ),
		'<p>Mit einem Geschenk von Schiesser verschenken Sie auch ein Stück <a href="{H}/geschichte/">Basler Geschichte</a>: die einer Confiserie, die seit 1870 am Marktplatz steht.</p>' => array( '<p>Avec un cadeau Schiesser, vous offrez aussi un morceau d’<a href="{H}/geschichte/">histoire bâloise</a> : celle d’une confiserie installée sur le Marktplatz depuis 1870.</p>', '<p>With a gift from Schiesser you also give a piece of <a href="{H}/geschichte/">Basel history</a>: that of a confectionery that has stood on the Marktplatz since 1870.</p>' ),
		'So läuft es ab' => array( 'Comment ça se passe', 'How it works' ),
		'Drei Schritte, ohne kompliziertes Formular.' => array( 'Trois étapes, sans formulaire compliqué.', 'Three steps, no complicated form.' ),
		'Sie schreiben uns' => array( 'Vous nous écrivez', 'You write to us' ),
		'Menge, Format und gewünschtes Übergabedatum, per E-Mail oder Telefon.' => array( 'Quantité, format et date de remise souhaitée, par e-mail ou par téléphone.', 'Quantity, format and preferred hand-over date, by email or phone.' ),
		'Wir antworten' => array( 'Nous vous répondons', 'We reply' ),
		'Innert ein bis zwei Arbeitstagen, mit einem Vorschlag und einem Preis.' => array( 'Sous un à deux jours ouvrables, avec une proposition et un prix.', 'Within one or two working days, with a proposal and a price.' ),
		'Wir bereiten vor' => array( 'Nous préparons', 'We prepare' ),
		'Ihre Geschenke werden kurz vor dem Übergabedatum zusammengestellt und am Marktplatz abgeholt.' => array( 'Vos cadeaux sont composés peu avant la date de remise et retirés au Marktplatz.', 'Your gifts are put together shortly before the hand-over date and collected at the Marktplatz.' ),
		'Für eine schnelle Offerte' => array( 'Pour une offre rapide', 'For a quick quote' ),
